        for (size_t p = i; p < j; ++p) {
            if (events[p].value > best[events[p].to]) {
                best[events[p].to] = events[p].value;
            }
        }

        i = j;
    }

    printf("%d\n", answer);

    free(events);
    free(best);
    free(x);
    free(y);
    return 0;
}
